}

export interface SidebarMenuItemProps extends ItemProps {}
export function SidebarMenuItem(props: ParentProps<SidebarMenuItemProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'ref']);
	return (
		<li {...rest} ref={local.ref} data-slot="sidebar-menu-item" class={`${styles[sidebarStyleKeys.menuItem]} ${local.class ?? ''}`}>
			{local.children}
		</li>
	);
}

export type SidebarMenuButtonTooltip = string | (Omit<TooltipContentProps, 'children'> & { children: JSX.Element });
export interface SidebarMenuButtonProps extends Omit<JSX.ButtonHTMLAttributes<HTMLButtonElement>, 'ref'> {
	ref?: CallbackRef<HTMLButtonElement>;
	isActive?: boolean;
	tooltip?: SidebarMenuButtonTooltip;
	variant?: SidebarMenuButtonVariant;
	size?: SidebarMenuButtonSize;
}

export function SidebarMenuButton(props: ParentProps<SidebarMenuButtonProps>) {
	const context = useContext(SidebarContext);
	if (!context) throw new Error('SidebarMenuButton must be used within a <SidebarProvider>.');
	const [local, rest] = splitProps(props, ['class', 'children', 'ref', 'isActive', 'tooltip', 'variant', 'size', 'type']);
	const variant = () => local.variant ?? 'default';
	const size = () => local.size ?? 'default';
	const styleKeys = () => getSidebarMenuButtonStyleKeys(variant(), size());
	const className = () => `${styles[styleKeys().base]} ${styles[styleKeys().variant]} ${styles[styleKeys().size]} ${local.class ?? ''}`;
	const tooltipProps = () => (typeof local.tooltip === 'string' ? { children: local.tooltip } : local.tooltip);
	const buttonProps = () => ({
		...rest,
		ref: local.ref,
		type: local.type ?? 'button',
		'data-slot': 'sidebar-menu-button',
		'data-size': size(),
		'data-active': local.isActive ?? false,
		class: className(),
	});

	return (
		<Show when={local.tooltip && !context.isMobile() && context.state() === 'collapsed'} fallback={<button {...buttonProps()}>{local.children}</button>}>
			<Tooltip>
				<TooltipTrigger {...buttonProps()}>{local.children}</TooltipTrigger>
				<TooltipContent side="right" {...tooltipProps()!} />
			</Tooltip>
		</Show>
	);
}

export interface SidebarMenuActionProps extends Omit<JSX.ButtonHTMLAttributes<HTMLButtonElement>, 'ref'> {
	ref?: CallbackRef<HTMLButtonElement>;
	showOnHover?: boolean;
}
export function SidebarMenuAction(props: ParentProps<SidebarMenuActionProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'ref', 'showOnHover', 'type']);
	return (
		<button
			{...rest}
			ref={local.ref}
			type={local.type ?? 'button'}
			data-slot="sidebar-menu-action"
			data-show-on-hover={local.showOnHover ?? false}
			class={`${styles[sidebarStyleKeys.menuAction]} ${local.class ?? ''}`}>
			{local.children}
		</button>
	);
}

export interface SidebarMenuBadgeProps extends DivProps {}
export function SidebarMenuBadge(props: ParentProps<SidebarMenuBadgeProps>) {
	return StyledDiv(props, 'sidebar-menu-badge', 'menuBadge');
}

export interface SidebarMenuSkeletonProps extends DivProps {
	showIcon?: boolean;
	width?: string;
}
export function SidebarMenuSkeleton(props: SidebarMenuSkeletonProps) {
	const [local, rest] = splitProps(props, ['class', 'ref', 'showIcon', 'width']);
	return (
		<div {...rest} ref={local.ref} data-slot="sidebar-menu-skeleton" class={`${styles[sidebarStyleKeys.skeleton]} ${local.class ?? ''}`}>
			<Show when={local.showIcon}>
				<Skeleton class={styles[sidebarStyleKeys.skeletonIcon]} />
			</Show>
			<Skeleton class={styles[sidebarStyleKeys.skeletonText]} style={{ '--skeleton-width': local.width ?? '70%' }} />
		</div>
	);
}

export interface SidebarMenuSubProps extends ListProps {}
export function SidebarMenuSub(props: ParentProps<SidebarMenuSubProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'ref']);
	return (
		<ul {...rest} ref={local.ref} data-slot="sidebar-menu-sub" class={`${styles[sidebarStyleKeys.menuSub]} ${local.class ?? ''}`}>
			{local.children}
		</ul>
	);
}
export interface SidebarMenuSubItemProps extends ItemProps {}
export function SidebarMenuSubItem(props: ParentProps<SidebarMenuSubItemProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'ref']);
	return (
		<li {...rest} ref={local.ref} data-slot="sidebar-menu-sub-item" class={`${styles[sidebarStyleKeys.menuSubItem]} ${local.class ?? ''}`}>
			{local.children}
		</li>
	);
}

export interface SidebarMenuSubButtonProps extends Omit<JSX.AnchorHTMLAttributes<HTMLAnchorElement>, 'ref'> {
	ref?: CallbackRef<HTMLAnchorElement>;
	size?: 'sm' | 'md';
	isActive?: boolean;
}
export function SidebarMenuSubButton(props: ParentProps<SidebarMenuSubButtonProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'ref', 'size', 'isActive']);
	const size = () => local.size ?? 'md';
	const styleKeys = () => getSidebarMenuSubButtonStyleKeys(size());
	return (
		<a
			{...rest}
			ref={local.ref}
			data-slot="sidebar-menu-sub-button"
			data-size={size()}
			data-active={local.isActive ?? false}
			aria-current={local.isActive ? (rest['aria-current'] ?? 'page') : rest['aria-current']}
			class={`${styles[styleKeys().base]} ${styles[styleKeys().size]} ${local.class ?? ''}`}>
			{local.children}
		</a>
	);
}

export default Sidebar;

@use '../../../styles/variables/colors' as *;

// 侧边栏使用标准 shadcn 扩展令牌。
$sidebar-bg: var(--tile-sidebar-background, var(--sidebar));
$sidebar-fg: var(--tile-sidebar-foreground, var(--sidebar-foreground));
$sidebar-border: var(--tile-sidebar-border, var(--sidebar-border));
$sidebar-accent: var(--tile-sidebar-hover-background, var(--sidebar-accent));
$sidebar-accent-fg: var(--tile-sidebar-hover-foreground, var(--sidebar-accent-foreground));
$sidebar-ring: var(--tile-sidebar-focus, var(--sidebar-ring));

// 根包裹层
.wrapper {
	display: flex;
	width: 100%;
	min-height: 100vh;
}

// 桌面端侧边栏
.container {
	display: none;
	flex-direction: column;
	flex-shrink: 0;
	width: var(--sidebar-width);
	overflow: hidden;
	transition: width $transition-normal;

	@media (min-width: 768px) {
		display: flex;
	}

	&[data-side='left'] {
		border-right: 1px solid $sidebar-border;
	}

	&[data-side='right'] {
		border-left: 1px solid $sidebar-border;
	}
}

// 折叠为 offcanvas 时收起
.container[data-collapsible='offcanvas'][data-state='collapsed'] {
	width: 0;
	border: none;
}

// 折叠为 icon 时收窄
.container[data-collapsible='icon'][data-state='collapsed'] {
	width: var(--sidebar-width-icon);
}

// 侧边栏主体
.sidebar {
	display: flex;
	flex-direction: column;
	width: 100%;
	flex: 1;
	background-color: $sidebar-bg;
	color: $sidebar-fg;
}

// floating 变体（data-variant 位于 .container 上）
.container[data-variant='floating'] .sidebar {
	border-radius: var(--tile-sidebar-panel-radius, $radius-lg);
	border: 1px solid $sidebar-border;
	box-shadow: var(--tile-sidebar-floating-shadow, $shadow-sm);
}

// 内容区
.content {
	display: flex;
	min-height: 0;
	flex: 1;
	flex-direction: column;
	gap: var(--tile-sidebar-content-gap, $spacing-2);
	overflow: auto;
}

.header,
.footer {
	display: flex;
	flex-direction: column;
	gap: $spacing-2;
	padding: var(--tile-sidebar-header-padding, $spacing-2);
}

// 分组
.group {
	position: relative;
	display: flex;
	width: 100%;
	min-width: 0;
	flex-direction: column;
	padding: var(--tile-sidebar-group-padding, $spacing-2);
}

.groupLabel {
	display: flex;
	height: 2rem;
	flex-shrink: 0;
	align-items: center;
	border-radius: $radius;
	padding-inline: $spacing-2;
	font-size: $text-xs;
	font-weight: $font-medium;
	color: var(--tile-sidebar-label-foreground, color-mix(in srgb, $sidebar-fg 70%, transparent));

	svg {
		width: 1rem;
		height: 1rem;
		flex-shrink: 0;
	}
}

.groupAction {
	position: absolute;
	top: $spacing-3;
	right: $spacing-3;
	display: flex;
	aspect-ratio: 1;
	width: 1.25rem;
	align-items: center;
	justify-content: center;
	border: none;
	border-radius: $radius;
	padding: 0;
	background-color: transparent;
	color: $sidebar-fg;
	cursor: pointer;

	&:hover {
		background-color: $sidebar-accent;
		color: $sidebar-accent-fg;
	}

	svg {
		width: 1rem;
		height: 1rem;
	}
}

.groupContent {
	width: 100%;
	font-size: $text-sm;
}

// 菜单
.menu {
	display: flex;
	width: 100%;
	min-width: 0;
	flex-direction: column;
	gap: var(--tile-sidebar-menu-gap, $spacing-1);
	margin: 0;
	padding: 0;
	list-style: none;
}

.menuItem {
	position: relative;
}

// 菜单按钮
.menuButton {
	display: flex;
	width: 100%;
	height: var(--tile-sidebar-button-height, 2rem);
	align-items: center;
	gap: var(--tile-sidebar-button-gap, $spacing-2);
	overflow: hidden;
	border: none;
	border-radius: var(--tile-sidebar-button-radius, $radius);
	background-color: transparent;
	color: $sidebar-fg;
	text-align: left;
	font-size: $text-sm;
	cursor: pointer;
	outline: none;
	transition:
		width $transition-normal,
		height $transition-normal,
		padding $transition-normal;

	&:hover {
		background-color: $sidebar-accent;
		color: $sidebar-accent-fg;
	}

	&:focus-visible {
		box-shadow: 0 0 0 2px $sidebar-ring;
	}

	&[data-active='true'] {
		background-color: var(--tile-sidebar-active-background, $sidebar-accent);
		font-weight: $font-medium;
		color: var(--tile-sidebar-active-foreground, $sidebar-accent-fg);
	}

	svg {
		width: 1rem;
		height: 1rem;
		flex-shrink: 0;
	}

	> span:last-child {
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}
}

// 菜单按钮变体
.variantDefault {
	&:hover {
		background-color: $sidebar-accent;
		color: $sidebar-accent-fg;
	}
}

.variantOutline {
	background-color: var(--tile-sidebar-outline-background, $background);
	box-shadow: 0 0 0 1px $sidebar-border;

	&:hover {
		background-color: $sidebar-accent;
		color: $sidebar-accent-fg;
		box-shadow: 0 0 0 1px $sidebar-accent;
	}
}

// 菜单按钮尺寸 (sizeSm 与子菜单按钮共享)
.sizeDefault {
	height: var(--tile-sidebar-button-height, 2rem);
	padding: var(--tile-sidebar-button-padding, $spacing-2);
}

.sizeSm {
	height: var(--tile-sidebar-sm-height, 1.75rem);
	padding-inline: $spacing-2;
	font-size: var(--tile-sidebar-sm-font-size, $text-xs);
}

.sizeLg {
	height: var(--tile-sidebar-lg-height, 3rem);
	padding: var(--tile-sidebar-button-padding, $spacing-2);
}

// 菜单操作按钮
.menuAction {
	position: absolute;
	top: $spacing-1_5;
	right: $spacing-1;
	display: flex;
	aspect-ratio: 1;
	width: 1.25rem;
	align-items: center;
	justify-content: center;
	border: none;
	border-radius: $radius;
	padding: 0;
	background-color: transparent;
	color: $sidebar-fg;
	cursor: pointer;

	&:hover {
		background-color: $sidebar-accent;
		color: $sidebar-accent-fg;
	}

	svg {
		width: 1rem;
		height: 1rem;
	}
}

// 菜单徽标
.menuBadge {
	position: absolute;
	right: $spacing-1;
	display: flex;
	height: 1.25rem;
	min-width: 1.25rem;
	align-items: center;
	justify-content: center;
	border-radius: $radius;
	padding-inline: $spacing-1;
	font-size: $text-xs;
	font-weight: $font-medium;
	color: $sidebar-fg;
	pointer-events: none;
	font-variant-numeric: tabular-nums;
}

// 子菜单
.menuSub {
	display: flex;
	min-width: 0;
	flex-direction: column;
	gap: $spacing-1;
	margin: 0;
	padding: $spacing-2 0;
	padding-left: $spacing-2_5;
	border-left: 1px solid $sidebar-border;
	list-style: none;
}

.menuSubItem {
	position: relative;
}

.menuSubButton {
	display: flex;
	height: 1.75rem;
	min-width: 0;
	align-items: center;
	gap: $spacing-2;
	overflow: hidden;
	border: none;
	border-radius: var(--tile-sidebar-button-radius, $radius);
	padding-inline: $spacing-2;
	background-color: transparent;
	color: $sidebar-fg;
	font-size: $text-sm;
	text-align: left;
	cursor: pointer;
	outline: none;

	&:hover {
		background-color: $sidebar-accent;
		color: $sidebar-accent-fg;
	}

	&[data-active='true'] {
		background-color: var(--tile-sidebar-active-background, $sidebar-accent);
		color: var(--tile-sidebar-active-foreground, $sidebar-accent-fg);
	}

	svg {
		width: 1rem;
		height: 1rem;
		flex-shrink: 0;
	}

	> span:last-child {
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}
}

// 子菜单按钮尺寸 (sizeSm 与菜单按钮共享)
.sizeMd {
	font-size: $text-sm;
}

// 触发器按钮
.trigger {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 1.75rem;
	height: 1.75rem;
	border: none;
	border-radius: var(--tile-sidebar-button-radius, $radius);
	background-color: transparent;
	color: var(--tile-sidebar-foreground, $foreground);
	cursor: pointer;

	&:hover {
		background-color: var(--tile-sidebar-hover-background, $accent);
		color: var(--tile-sidebar-hover-foreground, $accent-foreground);
	}

	svg {
		width: 1rem;
		height: 1rem;
	}
}

// 分隔线
.separator {
	width: 100%;
}

// 输入框
.input {
	width: 100%;
	height: 2rem;
	background-color: var(--tile-sidebar-input-background, $background);
	border: 1px solid $sidebar-border;
	border-radius: var(--tile-sidebar-button-radius, $radius);
	padding-inline: $spacing-2;
	font-size: $text-sm;
	color: var(--tile-sidebar-foreground, $foreground);
	box-shadow: none;

	&:focus {
		outline: none;
		border-color: $sidebar-ring;
		box-shadow: 0 0 0 1px $sidebar-ring;
	}
}

// 侧边栏占位 inset
.inset {
	position: relative;
	display: flex;
	width: 100%;
	flex: 1;
	flex-direction: column;
	background-color: var(--tile-sidebar-inset-background, $background);
}

// 折叠为 icon 时隐藏文本内容
.container[data-collapsible='icon'][data-state='collapsed'] {
	.groupLabel,
	.menuButton > span:last-child,
	.menuSubButton > span:last-child,
	.menuBadge,
	.menuSub,
	.groupAction {
		display: none;
	}

	.menuButton {
		width: 2rem;
		height: 2rem;
		padding: $spacing-2;
		justify-content: center;
	}
}

// 骨架屏
.skeleton {
	display: flex;
	height: 2rem;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius;
	padding-inline: $spacing-2;
}

.skeletonIcon {
	width: 1rem;
	height: 1rem;
	border-radius: $radius;
}

.skeletonText {
	height: 1rem;
	max-width: var(--skeleton-width);
	flex: 1;
}

// 仅供读屏
.srOnly {
	position: absolute;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	clip: rect(0, 0, 0, 0);
	white-space: nowrap;
	border-width: 0;
}

@media (prefers-reduced-motion: reduce) {
	.container,
	.menuButton {
		transition: none;
	}
}
